      (3, 14585, 3, '2010101001', 1, null, 0, 312.45, null, null),
      (3, 14586, 1, '6010103006', 1, null, 126, 0, null, null),
      (3, 14586, 2, '1010101001', 1, null, 0, 126, null, null),
      (3, 14587, 1, '6010103032', 1, null, 103.3, 0, null, null),
      (3, 14587, 2, '1010401001', 1, null, 12.4, 0, null, null),
      (3, 14587, 3, '1010101001', 1, null, 0, 115.7, null, null),
      (3, 14588, 1, '5010102003', 1, null, 87543.05, 0, null, null),
      (3, 14588, 2, '1010401001', 1, null, 17508.61, 0, null, null),
      (3, 14588, 3, '2010101002', 1, null, 0, 163413.7, null, null),
      (3, 14588, 4, '6010101001', 1, null, 58362.04, 0, null, null),
      (3, 14589, 1, '6010104001', 1, null, 68.7, 0, null, null),
      (3, 14589, 2, '1010401001', 1, null, 8.24, 0, null, null),
      (3, 14589, 3, '1010101001', 1, null, 0, 76.94, null, null),
      (3, 14590, 1, '6010103032', 1, null, 57.14, 0, null, null),
      (3, 14590, 2, '1010401001', 1, null, 6.86, 0, null, null),
      (3, 14590, 3, '1010101001', 1, null, 0, 64, null, null),
      (3, 14591, 1, '6010102003', 1, null, 100, 0, null, null),
      (3, 14591, 2, '1010101001', 1, null, 0, 100, null, null),
      (3, 14592, 1, '6010103032', 1, null, 8.93, 0, null, null),
